  function renderSecurity(){const d=state.security,s=d.resumo||{},root=$("ccSecurityRoot");root.innerHTML=`${pageHero("SEGURANÇA & AUDITORIA",`Segurança em <em>tempo real</em>`,"Revogações, bloqueios e alterações administrativas registradas pelo backend.",`<div class="cc-hero-note">${icon("shield")} Auditoria persistente no MySQL</div>`)}<section class="cc-security-full-kpis">${kpi("Revogações 24h",num(s.revogacoes24h),"logout","")}${kpi("Contas suspensas",num(s.contasSuspensas),"ban","red")}${kpi("Contas bloqueadas",num(s.contasBloqueadas),"lock","gold")}${kpi("Eventos 24h",num(s.eventos24h),"activity","blue")}${kpi("Eventos críticos",num(s.eventosCriticos24h),"shield","red")}</section><article class="cc-card"><header class="cc-card-head"><div class="cc-card-title"><span class="cc-card-icon">${icon("shield")}</span><div><strong>Timeline de Auditoria</strong><small>Eventos registrados pelo servidor</small></div></div><button class="cc-ghost-btn" data-refresh-security>Atualizar</button></header><div class="cc-audit-filters"><button class="active" data-security-filter="all">Todos</button><button data-security-filter="login">Login</button><button data-security-filter="role">Permissões</button><button data-security-filter="session">Sessões</button><button data-security-filter="account">Contas</button></div><div class="cc-security-events" id="ccSecurityEvents">${securityEvents(d.eventos||[])}</div></article>`;}
  function securityEvents(items){return items.length?items.map(e=>`<div class="cc-security-event"><code>${esc(String(e.evento||"EVENT").toUpperCase().replaceAll(".","_"))}</code><span>${esc(e.alvo||e.ator||"Sistema")}</span><time>${esc(relative(e.createdAt))}</time></div>`).join(""):empty("Nenhum evento registrado.");}
  function filterSecurity(filter){const items=(state.security?.eventos||[]).filter(e=>{if(filter==="all")return true;const v=String(e.evento||"").toLowerCase();if(filter==="login")return v.includes("login")||v.includes("auth");if(filter==="role")return v.includes("role")||v.includes("permission")||v.includes("staff");if(filter==="session")return v.includes("session")||v.includes("logout")||v.includes("token");if(filter==="account")return v.includes("block")||v.includes("suspend")||v.includes("account")||v.includes("premium");return true;});$("ccSecurityEvents").innerHTML=securityEvents(items);}

